-- 202611111730 · UN AGENTE MIRA EL VIDEO ANTES DE LA BANDEJA · GO Lenovo 11-nov 16:43 Zúrich (decisión de Emilio 16:41: «material premium sin ver el dinero»)
-- La plantilla video_mesa suma 2 pasos entre «video» y «chequeos»:
--   cuadros_video (código, sin modelo): un cuadro del medio de cada plano del guion (ffmpeg), guardado en la carpeta del encargo; sin cuadros → ficha que bloquea
--   mirar_video (agente con visión, video-editor, tope US$ 0,5): compara los cuadros con los planos del guion y la fila; JUZGA el agente (mirada_video.v1)
-- Solo cambia las columnas pasos e indicaciones (la indicación de quien mira el video; el dato EXACTO de src/lib/oficina/plantillas/video-mesa.ts; una prueba lo mantiene igual). Aditivo, sin borrar filas.
-- mirar_video lleva «vuelve_a» (mecanismo de 202611111700, CC4): si no coincide, el video vuelve UNA vez a la mesa con lo que faltó; a la segunda sigue con la ficha que bloquea.
-- ORDEN: DESPUÉS de 202611111700 (la guarda exige su dato exacto). Se niega con encargos de video vivos (las posiciones de los pasos cambian). Reversa: reversas/202611111730_oficina_un_agente_mira_el_video_REVERSA.sql
BEGIN;

DO $$
BEGIN
  -- insertar o quitar pasos corre las posiciones: un encargo de video VIVO quedaría apuntando al paso equivocado
  IF EXISTS (SELECT 1 FROM public.oficina_encargos WHERE familia = 'video_mesa' AND estado IN ('abierto', 'en_paso')) THEN
    RAISE EXCEPTION '202611111730: hay encargos de video vivos; esperar a que cierren';
  END IF;
  IF (SELECT array_agg(x.p->>'clave' ORDER BY x.o) FROM public.oficina_tipos_de_grupo t, jsonb_array_elements(t.pasos) WITH ORDINALITY AS x(p, o) WHERE t.familia = 'video_mesa') IS DISTINCT FROM ARRAY['abrir','mesa','pedido','video','chequeos','jefatura','chequeos_2','entrega','cierre'] THEN
    RAISE EXCEPTION '202611111730: la plantilla video_mesa no tiene los pasos esperados';
  END IF;
  -- y el dato de antes, ENTERO, es el esperado: si alguien lo cambió, no se pisa
  IF (SELECT pasos FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $antes$[{"clave":"abrir","tipo":"codigo","quien":"sala","funcion":"abrir_video","condicion":{"tipo":"siempre"},"entrada":[],"salida_artefacto":"encargo","tope_usd":0},{"clave":"mesa","tipo":"codigo","quien":"sala","funcion":"mesa","condicion":{"tipo":"siempre"},"entrada":["encargo"],"salida_artefacto":"mesa","tope_usd":0},{"clave":"pedido","tipo":"codigo","quien":"sala","funcion":"pedido_de_video","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video"],"salida_artefacto":"pedido_video","tope_usd":0,"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"pedido_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"video","tipo":"codigo","quien":"sala","funcion":"video","condicion":{"tipo":"siempre"},"entrada":["pedido_video"],"salida_artefacto":"video","tope_usd":5},{"clave":"chequeos","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"siempre"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"jefatura","tipo":"jefatura","quien":"jefatura","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video","video","chequeos"],"salida_artefacto":"respuesta_imagen","tope_usd":0},{"clave":"chequeos_2","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"entrega","tipo":"codigo","quien":"sala","funcion":"empaquetar_entrega_video","condicion":{"tipo":"siempre"},"entrada":["copy_video","video","chequeos","guion"],"salida_artefacto":"entrega","tope_usd":0},{"clave":"cierre","tipo":"codigo","quien":"sala","funcion":"cierre","condicion":{"tipo":"siempre"},"entrada":["entrega"],"salida_artefacto":"cierre","tope_usd":0}]$antes$::jsonb THEN
    RAISE EXCEPTION '202611111730: el dato de la plantilla video_mesa no es el esperado; no se pisa';
  END IF;
  IF (SELECT indicaciones FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $ind_antes${}$ind_antes$::jsonb THEN
    RAISE EXCEPTION '202611111730: las indicaciones de video_mesa no son las esperadas; no se pisan';
  END IF;
END $$;

UPDATE public.oficina_tipos_de_grupo SET pasos = $pasos$[{"clave":"abrir","tipo":"codigo","quien":"sala","funcion":"abrir_video","condicion":{"tipo":"siempre"},"entrada":[],"salida_artefacto":"encargo","tope_usd":0},{"clave":"mesa","tipo":"codigo","quien":"sala","funcion":"mesa","condicion":{"tipo":"siempre"},"entrada":["encargo"],"salida_artefacto":"mesa","tope_usd":0},{"clave":"pedido","tipo":"codigo","quien":"sala","funcion":"pedido_de_video","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video"],"salida_artefacto":"pedido_video","tope_usd":0,"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"pedido_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"video","tipo":"codigo","quien":"sala","funcion":"video","condicion":{"tipo":"siempre"},"entrada":["pedido_video"],"salida_artefacto":"video","tope_usd":5},{"clave":"cuadros_video","tipo":"codigo","quien":"sala","funcion":"cuadros_video","condicion":{"tipo":"siempre"},"entrada":["video","guion"],"salida_artefacto":"cuadros_video","tope_usd":0},{"clave":"mirar_video","tipo":"agente","quien":"video-editor","condicion":{"tipo":"si_artefacto","artefacto":"cuadros_video","campo":"hay_cuadros","igual":true},"entrada":["cuadros_video","guion"],"salida_artefacto":"mirada_video","tope_usd":0.5,"salida":{"esquema":"mirada_video.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"mirada_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"chequeos","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"siempre"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"jefatura","tipo":"jefatura","quien":"jefatura","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video","video","chequeos"],"salida_artefacto":"respuesta_imagen","tope_usd":0},{"clave":"chequeos_2","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"entrega","tipo":"codigo","quien":"sala","funcion":"empaquetar_entrega_video","condicion":{"tipo":"siempre"},"entrada":["copy_video","video","chequeos","guion"],"salida_artefacto":"entrega","tope_usd":0},{"clave":"cierre","tipo":"codigo","quien":"sala","funcion":"cierre","condicion":{"tipo":"siempre"},"entrada":["entrega"],"salida_artefacto":"cierre","tope_usd":0}]$pasos$::jsonb, indicaciones = $ind${"video-editor":[{"regla":"Cuando miras el video terminado, juzgas tú si cuenta lo que pide el guion y la fila: describe lo que de verdad se ve en cada cuadro, sin suponer lo que no se ve, y di qué falta para que el video cuente la historia.","aplica":"guia"}]}$ind$::jsonb WHERE familia = 'video_mesa';

DO $$
BEGIN
  IF (SELECT array_agg(x.p->>'clave' ORDER BY x.o) FROM public.oficina_tipos_de_grupo t, jsonb_array_elements(t.pasos) WITH ORDINALITY AS x(p, o) WHERE t.familia = 'video_mesa') IS DISTINCT FROM ARRAY['abrir','mesa','pedido','video','cuadros_video','mirar_video','chequeos','jefatura','chequeos_2','entrega','cierre'] THEN
    RAISE EXCEPTION '202611111730: la plantilla video_mesa no quedó con los pasos nuevos';
  END IF;
END $$;

COMMIT;
